        "mars": 4,
        "jupiter": 5,
        "saturn": 6,
        "uranus": 7,
        "neptune": 8
    }

    if planet1.lower() not in planets or planet2.lower() not in planets:
        return ()

    orbit1 = planets[planet1.lower()]
    orbit2 = planets[planet2.lower()]

    if orbit1 == orbit2:
        return ()

